package com.nypunya.assessment.service;
import com.nypunya.assessment.dto.QuizOptionRequest; import com.nypunya.assessment.entity.*; import com.nypunya.assessment.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List; import java.util.NoSuchElementException;
@Service public class QuizAuthoringService { private final QuizRepository quizzes; private final QuizQuestionRepository questions; private final QuizOptionRepository options; public QuizAuthoringService(QuizRepository q,QuizQuestionRepository qs,QuizOptionRepository o){quizzes=q;questions=qs;options=o;}
 @Transactional public QuizOption addOption(Long quizId,Long questionId,QuizOptionRequest r,Long trainerId){Quiz q=quizzes.findById(quizId).orElseThrow(()->new NoSuchElementException("Quiz not found"));if(!q.getTrainerId().equals(trainerId))throw new SecurityException("Not quiz owner");if(q.getStatus()!=QuizStatus.DRAFT)throw new IllegalStateException("Only draft quizzes can be edited");QuizQuestion question=questions.findById(questionId).orElseThrow(()->new NoSuchElementException("Question not found"));if(!question.getQuizId().equals(quizId))throw new IllegalArgumentException("Question does not belong to quiz");QuizOption o=new QuizOption();o.setQuestionId(questionId);o.setText(r.getText().trim());o.setCorrect(r.getCorrect());return options.save(o);}
 @Transactional(readOnly=true) public List<QuizOption> options(Long quizId,Long questionId,Long trainerId){Quiz q=quizzes.findById(quizId).orElseThrow(()->new NoSuchElementException("Quiz not found"));if(!q.getTrainerId().equals(trainerId))throw new SecurityException("Not quiz owner");QuizQuestion question=questions.findById(questionId).orElseThrow(()->new NoSuchElementException("Question not found"));if(!question.getQuizId().equals(quizId))throw new IllegalArgumentException("Question does not belong to quiz");return options.findByQuestionId(questionId);}
}
